def count_subsequence_matches(text: str, sub: str) -> int:
    def backtrack(index, sub_index):
        if sub_index == len(sub):
            return 1
        if index == len(text):
            return 0

        # Include the current character in the subsequence
        include = backtrack(index + 1, sub_index + 1) if text[index] == sub[sub_index] else 0

        # Exclude the current character from the subsequence
        exclude = backtrack(index + 1, sub_index)

        return include + exclude

    return backtrack(0, 0)
```

