def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return "0"

    digits = []
    is_negative = n < 0
    n = abs(n)

    while n > 0:
        remainder = n % 3
        if remainder == 2:
            digits.append('-')
            n = (n + 1) // 3
        elif remainder == 1:
            digits.append('+')
            n = n // 3
        else:
            digits.append('0')
            n = n // 3

    if is_negative:
        digits.append('-')

    return ''.join(reversed(digits))
```

