from typing import List

def min_coins_bounded(coins: List[int], limits: List[int], target: int) -> int:
    if target == 0:
        return 0

    n = len(coins)

    # Initialize a DP table where dp[i] represents the minimum number of coins needed to make amount i
    dp = [float('inf')] * (target + 1)
    dp[0] = 0  # Base case: 0 coins needed to make amount 0

    for i in range(1, target + 1):
        for j in range(n):
            if coins[j] <= i and limits[j] > 0:
                dp[i] = min(dp[i], dp[i - coins[j]] + 1)
                limits[j] -= 1

    return dp[target] if dp[target] != float('inf') else -1
