            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # The LCS is built backwards, so reverse it
    lcs.reverse()

    # If no common characters, return an empty string
    if not lcs:
