    if n == 0:
        return 1

    def is_valid_position(row: int, col: int) -> bool:
        for b_row, b_col in blocked:
            if b_row == row or b_col == col or abs(b_row - row) == abs(b_col - col):
                return False
        return True

    def backtrack(row: int) -> int:
        if row == n:
            return 1

        count = 0
        for col in range(n):
            if is_valid_position(row, col):
                blocked.append((row, col))
                count += backtrack(row + 1)
                blocked.pop()

