from math import gcd
from functools import reduce

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    M = reduce(lcm, [m for _, m in congruences])
    solutions = []

    for r, m in congruences:
        M_i = M // m
        y = pow(M_i, -1, m)
        x = (r * M_i * y) % M
        solutions.append(x)

    if len(set(solutions)) == len(solutions):
        return (min(solutions), M)
    else:
        return None
