def evaluate_expression(expression: str) -> float:
    def parse_expression(tokens):
        if not tokens:
            raise ValueError("Invalid expression")

        def evaluate(tokens):
            if not tokens:
                raise ValueError("Invalid expression")

            token = tokens.pop(0)
            if token.isdigit():
                return float(token)
            elif token == '(':
                result = evaluate(tokens)
                if tokens.pop(0) != ')':
                    raise ValueError("Invalid expression")
                return result
            elif token in ('+', '-', '*', '/', '**'):
                right = evaluate(tokens)
                left = evaluate(tokens)
                if token == '+':
                    return left + right
                elif token == '-':
                    return left - right
                elif token == '*':
                    return left * right
                elif token == '/':
                    if right == 0:
                        raise ZeroDivisionError("Division by zero")
                    return left / right
                elif token == '**':
                    return left ** right
            else:
                raise ValueError("Invalid expression")

        return evaluate(list(filter(lambda x: x != ' ', expression.split())))

    try:
        return parse_expression(expression)
    except (ZeroDivisionError, ValueError) as e:
        raise e
