def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid or not grid[0]:
        return []

    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0])

    while True:
        overflow = False
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] > 3:
                    overflow = True
                    grid[r][c] -= 4
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if is_valid(nr, nc):
                            grid[nr][nc] += 1

        if not overflow:
            break

    return grid
