from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize the queue with the starting position and the number of moves
    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current, moves = queue.popleft()

        # If we reach the end, return the number of moves
        if current == end:
            return moves

        # Explore all four possible directions
        for dx, dy in directions:
            nx, ny = current[0] + dx, current[1] + dy

            # Check if the new position is within bounds and not a wall
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#':
                # If the new position has not been visited, mark it as visited and add to the queue
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), moves + 1))

    # If we exhaust the queue without finding the end, return -1
    return -1
