def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    changes = True

    while changes:
        changes = False
        new_grid = [[0] * cols for _ in range(rows)]

        for r in range(rows):
            for c in range(cols):
                grains = grid[r][c]
                if grains >= 4:
                    changes = True
                    new_grid[r][c] -= 4
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            new_grid[nr][nc] += 1

        grid = new_grid

    return grid
