def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    if not sizes:
        return []

    bins = []
    for size in sorted(sizes, reverse=True):
        if size > capacity:
            raise ValueError("Element size exceeds capacity")

        found = False
        for i, bin in enumerate(bins):
            if sum(bin) + size <= capacity:
                bin.append(size)
                found = True
                break

        if not found:
            bins.append([size])

    return bins
