def tokenize_code(source: str) -> list[tuple[str, str]]:
    tokens = []
    i = 0
    while i < len(source):
        if source[i].isspace():
            i += 1
            continue
        elif source[i] == '.':
            if i + 1 < len(source) and source[i + 1].isdigit():
                tokens.append(('NUMBER', source[i:i + 2]))
                i += 2
            else:
                raise ValueError("Invalid number format")
        elif source[i].isalpha() or source[i] == '_':
            j = i
            while j < len(source) and (source[j].isalnum() or source[j] == '_'):
                j += 1
            tokens.append(('NAME', source[i:j]))
            i = j
        elif source[i] in '+-*/<=>=':
            if i + 1 < len(source) and source[i:i + 2] in '+-*/<=>=':
                tokens.append(('OP', source[i:i + 2]))
                i += 2
            else:
                tokens.append(('OP', source[i]))
                i += 1
        else:
            raise ValueError(f"Unexpected character: {source[i]}")
    return tokens
