def evaluate_expression(expr: str) -> int:
    def precedence(op):
        if op in ('^', '-'):
            return 3
        elif op in ('*', '/'):
            return 2
        elif op in ('+', '-'):
            return 1
        return 0

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            if right == 0:
                raise ZeroDivisionError("division by zero")
            values.append(int(left / right))
        elif operator == '^':
            values.append(left ** right)

    def evaluate(tokens):
        values = []
        operators = []
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if token.isdigit():
                values.append(int(token))
            elif token in ('+', '-', '*', '/', '^', '('):
                while (operators and operators[-1] != '(' and
                       precedence(operators[-1]) >= precedence(token)):
                    apply_operator(operators, values)
                operators.append(token)
            elif token == '(':
                operators.append(token)
            elif token == ')':
                while operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Remove '('
            i += 1
        while operators:
            apply_operator(operators, values)
        return values[0]

    tokens = expr.replace(' ', '').split()
    return evaluate(tokens)
```

