def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            # Calculate the new position after rotation
            new_i = (i + k) % n
            new_j = (j + k) % n

            # If the new position is within the same ring, copy the value
            if new_i == i and new_j == j:
                result[i][j] = matrix[i][j]
            else:
                # Otherwise, copy the value from the original matrix
                result[new_i][new_j] = matrix[i][j]

    return result
