def process_orders(events: List[Tuple[str, str, int]]) -> Tuple[Dict[str, int], List[Tuple[str, int]]]:
    stock: Dict[str, int] = {}
    waiting: List[Tuple[str, int]] = []

    for kind, item, quantity in events:
        if kind == 'receive':
            if item not in stock:
                stock[item] = 0
            stock[item] += quantity
        elif kind == 'order':
            if item not in stock:
                stock[item] = 0
            if stock[item] >= quantity:
                stock[item] -= quantity
                waiting.append((item, quantity))
            else:
                waiting.append((item, quantity))

    return stock, waiting
