def run_bank_ops(balances: dict[str, int], ops: list[tuple]) -> tuple[dict[str, int], list[int]]:
    final_balances = balances.copy()
    failed = []

    for i, op in enumerate(ops):
        account, amount = None, None
        if op[0] == 'deposit':
            account, amount = op[1], op[2]
        elif op[0] == 'withdraw':
            account, amount = op[1], op[2]
        elif op[0] == 'transfer':
            source, target, amount = op[1], op[2], op[3]
            if source == target:
                failed.append(i)
                continue
            if source not in balances or target not in balances:
                failed.append(i)
                continue
            if balances[source] < amount + 2:
                failed.append(i)
                continue
            if balances[source] < amount:
                failed.append(i)
                continue
            balances[source] -= amount + 2
            balances[target] += amount
        elif op[0] == 'freeze':
            account = op[1]
            if account not in balances:
                failed.append(i)
                continue
            balances[account] = -balances[account]
        elif op[0] == 'unfreeze':
            account = op[1]
            if account not in balances:
                failed.append(i)
                continue
            balances[account] = -balances[account]

    return final_balances, failed
